-- Verze heslo: žije v identity.user_secrets (RLS split), ne v identity.users.
-- Verze tam řádek nemá → zkopíruj bcrypt(Demo2026!) ze superadmina (bcrypt ověří
-- heslo bez ohledu na salt). Bez tohohle verze login selže (Invalid credentials).
INSERT INTO identity.user_secrets (user_id, password_hash, updated_at)
SELECT '00000000-0000-4000-a000-000000000115', us.password_hash, NOW()
  FROM identity.user_secrets us
  JOIN identity.users u ON u.id = us.user_id
 WHERE u.email = 'superadmin@tixly.cz'
 LIMIT 1
ON CONFLICT (user_id) DO UPDATE SET password_hash = EXCLUDED.password_hash, updated_at = NOW();

COMMIT;
